#include "qms/ReleaseReadinessGate.h"
namespace dnxr {
ReleaseReadinessDecision ReleaseReadinessGate::evaluate(const ReleaseReadinessEvidence& e) const { ReleaseReadinessDecision d; auto need=[&](bool ok,const char* gap){if(!ok)d.gaps.push_back(gap);}; need(e.cmakeConfigureOk,"cmake configure"); need(e.fullBuildOk,"full build"); need(e.ctestAllOk,"CTest all"); need(e.staticChecksOk,"static checks"); need(e.qmsDocsOk,"QMS docs"); need(e.traceabilityOk,"traceability"); need(e.noDisabledBlockingTests,"no disabled blocking tests"); need(e.hilP95P99Present,"HIL p95/p99"); need(e.safetyCasePresent,"safety case"); need(e.evidenceBundleGenerated,"evidence bundle"); need(e.noHumanUseClaims,"no human-use claims"); need(e.humanUseGateBlocked,"human-use gate blocked"); if(!e.humanUseGateBlocked || !e.noHumanUseClaims) d.status=ReleaseReadinessStatus::Blocked; else if(d.gaps.empty() && e.independentReviewPlanned) d.status=ReleaseReadinessStatus::MedicalReviewCandidate; else if(d.gaps.empty()) d.status=ReleaseReadinessStatus::RNDReleaseCandidate; else if(e.cmakeConfigureOk && e.staticChecksOk && e.qmsDocsOk) d.status=ReleaseReadinessStatus::InternalCandidate; else d.status=ReleaseReadinessStatus::Blocked; return d; }
}
